mapper.select:
SELECT s.DEV_ID AS "developerId",s.SKILL_NM AS "skillName" FROM TB_HR_DEV_SKILL s
WHERE s.DEV_ID IN #{id}
ORDER BY s.DEV_ID,s.SORT_ORD,s.SKILL_NM

 WHERE l.RCMD_TYPE_CD='AI'
  AND l.PROJ_ID=#{targetId}AND l.OPP_ID=#{targetId}
  AND l.SCORE_DTL LIKE '%"f":"' || #{fingerprint} || '"%'
  AND CASE WHEN left(l.SCORE_DTL,6)='{"v":1' THEN l.SCORE_DTL::jsonb->>'f' ELSE NULL END=#{fingerprint}
ORDER BY l.RCMD_ID,l.RANK_ORD
